(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-798":{scenario:{company:"Công ty Tổ chức Sự kiện Bình Minh Xanh",supervisor:{name:"Quách Gia Bảo",role:{vi:"Trưởng dự án Sự kiện",en:"Event Project Lead"}},ref_code:"EV-7720",title:{vi:"Đúng sơ đồ phòng. Đúng hợp đồng. An toàn phòng cháy.",en:"Right room set. Right contract. Fire safety first."},brief:{vi:"Bạn rà soát hồ sơ hội nghị khách hàng EV-7720 tại một khách sạn: phiên chiều là hội thảo có thảo luận nhóm 8 người mỗi bàn tròn, mọi người cùng nhìn lên sân khấu. Hợp đồng khối phòng cam kết 120 đêm phòng, cho phép hụt 20% không phạt, giá hợp đồng 2.400.000 đồng/đêm; thực tế khách dùng 82 đêm phòng (số liệu mô phỏng). Sửa kiểu bố trí phòng và phí bồi thường khối phòng, rồi lập báo cáo có căn cứ.",en:"You are reviewing client conference file EV-7720 at a hotel: the afternoon session is a workshop with group discussions of 8 people per round table, everyone facing the stage. The room block contract commits 120 room nights, allows 20% attrition without penalty, at 2,400,000 VND per night; actual use was 82 room nights (training figures). Correct the room setup and the room block attrition charge, then write an evidence-based report."},reference_title:{vi:"Kịch bản chương trình & hợp đồng khối phòng đã duyệt · EV-7720",en:"Approved programme & room block contract · EV-7720"},fields:[{id:"ROOM_SETUP",label:{vi:"Kiểu bố trí phòng phiên chiều",en:"Afternoon room setup"},initial:"Theater",expected:"Cabaret",choices:["Theater","Classroom","Cabaret"],reference:"Bảng chọn kiểu bố trí theo hình thức phiên",hint:{vi:"Phiên thảo luận nhóm cần bàn tròn, đồng thời người ngồi phải nhìn được sân khấu mà không quay lưng lại.",en:"Group discussion needs round tables, and every seat must face the stage without turning away."}},{id:"ATTRITION",label:{vi:"Phí bồi thường khối phòng (VND)",en:"Room block attrition charge (VND)"},initial:"91200000",expected:"33600000",reference:"Hợp đồng khối phòng đã ký",ref_value:{vi:"Cam kết 120 đêm; cho phép hụt 20%; thực tế 82 đêm; giá 2.400.000 đồng/đêm (mô phỏng)",en:"Commitment 120 nights; 20% attrition allowed; actual 82 nights; 2,400,000 VND per night (training)"},hint:{vi:"Chỉ phần hụt vượt quá mức cho phép mới bị tính phí, không phải toàn bộ số đêm chưa dùng.",en:"Only the shortfall beyond the allowed attrition is charged, not all unused nights."}}],sop32:{vi:"Phí bồi thường = (số đêm cam kết x (1 - tỷ lệ hụt cho phép) - số đêm thực tế) x giá hợp đồng; nếu thực tế đạt mức tối thiểu thì phí bằng 0 (điều khoản mô phỏng).",en:"Attrition charge = (committed nights x (1 - allowed attrition) - actual nights) x contract rate; if actual use reaches the minimum, the charge is zero (training clause)."},context:{label:"EVENT FILE / EV-7720",metrics:[{label:{vi:"Đêm phòng cam kết",en:"Committed room nights"},value:"120"},{label:{vi:"Hụt cho phép",en:"Allowed attrition"},value:"20%"},{label:{vi:"Đêm phòng thực tế",en:"Actual room nights"},value:"82"}]},crisis:{vi:"Đạo diễn sân khấu muốn đặt backdrop và thùng thiết bị chắn cửa thoát hiểm phía sau, kê thêm 30 ghế vượt sức chứa được duyệt của phòng: “Khách hàng muốn đông, khách sạn không kiểm tra đâu.”",en:"The stage director wants to place the backdrop and equipment cases across the rear fire exit and add 30 chairs beyond the room's approved capacity: “The client wants it packed, the hotel won't check.”"},options:{safe:{vi:"Không chắn lối thoát hiểm, giữ đúng sức chứa được duyệt; báo trưởng dự án và bộ phận an ninh khách sạn, đề xuất bố trí lại sân khấu hoặc phòng phụ có truyền hình trực tiếp.",en:"Keep the fire exit clear and the approved capacity; inform the project lead and hotel security, and propose a new stage layout or an overflow room with a live feed."},shortcut:{vi:"Cho đặt backdrop chắn cửa và kê thêm ghế, dỡ ra ngay sau khi sự kiện kết thúc.",en:"Allow the backdrop across the exit and the extra chairs, then clear them right after the event."},wait:{vi:"Để đạo diễn và khách sạn tự thỏa thuận, mình chỉ lo phần đón khách.",en:"Let the director and the hotel sort it out while you handle registration only."}},questions:{vi:["Vì sao bạn đổi kiểu bố trí phòng phiên chiều? Yêu cầu nào của chương trình chứng minh lựa chọn đó?","Trình bày cách tính phí bồi thường khối phòng và cách xử lý khi phương án sân khấu vi phạm an toàn phòng cháy."],en:["Why did you change the afternoon room setup? Which programme requirement supports your choice?","Explain how you calculated the attrition charge and how you handle a stage plan that breaches fire safety."]},hints:{vi:["Đọc mô tả hình thức phiên trong kịch bản chương trình rồi đối chiếu với bảng chọn kiểu bố trí.","Theo SOP mục 3.2: tính mức tối thiểu sau khi trừ tỷ lệ hụt cho phép, rồi mới so với số đêm thực tế.","Đọc lại SOP mục 4.2: lối thoát nạn và sức chứa được duyệt không được thay đổi theo yêu cầu thẩm mỹ."],en:["Read the session format in the programme and compare it with the room setup table.","Per SOP 3.2: compute the minimum after allowed attrition, then compare it with actual nights.","Re-read SOP 4.2: escape routes and approved capacity cannot change for aesthetic reasons."]}},learning:{summary:{vi:"Chuyên viên tổ chức sự kiện MICE lên kế hoạch và vận hành hội nghị, hội thảo, chương trình khen thưởng và triển lãm: chọn địa điểm, đàm phán hợp đồng khách sạn, khối phòng, suất ăn, sân khấu âm thanh ánh sáng, đăng ký đại biểu, vận chuyển và kịch bản chương trình. Mục tiêu là sự kiện đạt mục tiêu của khách hàng, đúng ngân sách và an toàn tuyệt đối. Nghề đòi hỏi kỹ năng quản lý dự án, đọc hợp đồng, tính toán chi phí và giữ vững tiêu chuẩn an toàn trước áp lực khách hàng.",en:"A MICE event coordinator plans and runs meetings, incentives, conferences and exhibitions: choosing venues, negotiating hotel contracts, room blocks, catering, staging and AV, delegate registration, transport and the run of show. The goal is an event that meets the client's objectives, stays on budget and is completely safe. The role needs project management, contract reading, cost control and the firmness to keep safety standards under client pressure."},responsibilities:{vi:["Khảo sát, đề xuất địa điểm và kiểu bố trí phòng theo mục tiêu, hình thức từng phiên.","Đàm phán, theo dõi hợp đồng khách sạn: khối phòng, ngày chốt, tỷ lệ hụt, cam kết suất ăn.","Lập ngân sách, kiểm soát chi phí nhà cung cấp và quyết toán sau sự kiện.","Xây dựng kịch bản chương trình, điều phối sân khấu, âm thanh, ánh sáng và đăng ký đại biểu.","Lập kế hoạch an toàn, phòng cháy, y tế, sơ tán và xử lý sự cố tại hiện trường."],en:["Scout venues and propose room setups to fit each session's goals and format.","Negotiate and track hotel contracts: room blocks, cut-off dates, attrition and catering guarantees.","Build the budget, control supplier costs and settle accounts after the event.","Write the run of show and coordinate staging, sound, lighting and registration.","Plan safety, fire protection, medical support, evacuation and on-site incident response."]},competencies:[{name:{vi:"Quản lý dự án sự kiện",en:"Event project management"},desc:{vi:"Lập tiến độ ngược từ ngày sự kiện, phân công rõ và kiểm soát mốc quan trọng.",en:"Plan backwards from event day, assign clearly and control key milestones."}},{name:{vi:"Đọc và kiểm soát hợp đồng",en:"Contract control"},desc:{vi:"Hiểu điều khoản khối phòng, tỷ lệ hụt, hủy, cam kết suất ăn và tính đúng nghĩa vụ tài chính.",en:"Understand room block, attrition, cancellation and guarantee clauses and compute liabilities correctly."}},{name:{vi:"Thiết kế không gian",en:"Space design"},desc:{vi:"Chọn kiểu bố trí phù hợp hình thức phiên, tính sức chứa và lưu thông an toàn.",en:"Choose setups that fit the session format and plan capacity and safe circulation."}},{name:{vi:"Điều phối nhà cung cấp",en:"Supplier coordination"},desc:{vi:"Làm việc với khách sạn, sân khấu, vận chuyển, in ấn theo một kịch bản thống nhất.",en:"Work with hotels, staging, transport and print suppliers to one shared run of show."}},{name:{vi:"An toàn & liêm chính",en:"Safety & integrity"},desc:{vi:"Giữ lối thoát nạn, sức chứa được duyệt, báo cáo minh bạch và từ chối chi phí khống.",en:"Keep escape routes and approved capacity, report transparently and refuse fictitious costs."}}],knowledge:{vi:["Điều khoản hợp đồng MICE: khối phòng, ngày chốt (cut-off), tỷ lệ hụt cho phép (attrition), cam kết suất ăn (guarantee).","Luật Phòng cháy, chữa cháy và cứu nạn, cứu hộ năm 2024: lối thoát nạn và sức chứa tại nơi tập trung đông người.","Quy định về tổ chức hội nghị, hội thảo có yếu tố nước ngoài tại Việt Nam: xin phép cơ quan có thẩm quyền khi thuộc diện phải xin phép.","ISO 20121 về hệ thống quản lý sự kiện bền vững.","Kiểu bố trí phòng theater, classroom, cabaret, banquet, U-shape và định mức diện tích mỗi người.","Quản lý rủi ro sự kiện: phương án dự phòng thời tiết, y tế, an ninh và sơ tán."],en:["MICE contract terms: room blocks, cut-off dates, allowed attrition and catering guarantees.","Law on Fire Prevention, Firefighting and Rescue of 2024: escape routes and capacity in crowded venues.","Vietnamese rules on international conferences and seminars: obtain approval from the competent authority where required.","ISO 20121 on event sustainability management systems.","Theater, classroom, cabaret, banquet and U-shape setups and space per person.","Event risk management: contingency plans for weather, medical, security and evacuation."]},tools:["Phần mềm quản lý sự kiện và đăng ký đại biểu","Phần mềm vẽ sơ đồ mặt bằng sự kiện","Bảng ngân sách và quyết toán sự kiện","Kịch bản chương trình chi tiết","Ứng dụng check-in bằng mã QR"],kpis:{vi:["Điểm hài lòng của khách hàng và đại biểu sau sự kiện.","Chênh lệch chi phí thực tế so với ngân sách được duyệt.","Tỷ lệ đại biểu đăng ký có mặt thực tế.","Số sự cố an toàn và kỹ thuật trong sự kiện (mục tiêu bằng 0)."],en:["Client and delegate satisfaction after the event.","Actual cost variance against the approved budget.","Share of registered delegates who attend.","Safety and technical incidents during the event (target zero)."]},day:[{time:"08:00",vi:"Rà soát phiếu yêu cầu dịch vụ tiệc (BEO) và danh sách đại biểu cập nhật.",en:"Review the banquet event orders (BEO) and the updated delegate list."},{time:"10:00",vi:"Khảo sát địa điểm cùng khách sạn: sơ đồ phòng, lối thoát nạn, điểm đặt sân khấu.",en:"Walk the venue with the hotel: floor plan, escape routes and stage position."},{time:"13:30",vi:"Họp nhà cung cấp sân khấu, âm thanh, ánh sáng và chốt kịch bản chương trình.",en:"Meet staging, sound and lighting suppliers and lock the run of show."},{time:"15:30",vi:"Theo dõi số đêm phòng đã đặt so với cam kết trước ngày chốt khối phòng.",en:"Track room block pickup against the commitment before the cut-off date."},{time:"18:00",vi:"Tổng duyệt chương trình, kiểm tra an toàn hiện trường và bàn giao ca trực.",en:"Run the rehearsal, check on-site safety and hand over the duty shift."}],mistakes:{vi:["Chọn kiểu bố trí theo thói quen thay vì theo hình thức và mục tiêu của từng phiên.","Tính phí bồi thường trên toàn bộ số đêm chưa dùng, bỏ qua tỷ lệ hụt cho phép.","Chấp nhận chắn lối thoát hiểm hoặc vượt sức chứa để chiều ý khách hàng."],en:["Choosing a setup out of habit instead of each session's format and goal.","Charging attrition on all unused nights and ignoring the allowed percentage.","Accepting blocked exits or overcapacity to please the client."]},career:[{vi:"Trợ lý tổ chức sự kiện",en:"Event assistant"},{vi:"Chuyên viên tổ chức sự kiện MICE",en:"MICE event coordinator"},{vi:"Trưởng dự án sự kiện",en:"Event project lead"},{vi:"Giám đốc MICE và sự kiện",en:"Director of MICE and events"}],glossary:[{term:"MICE",vi:"Loại hình du lịch kết hợp hội họp, khen thưởng, hội nghị và triển lãm.",en:"Meetings, incentives, conferences and exhibitions as a travel segment."},{term:"Attrition",vi:"Tỷ lệ hụt cho phép so với số đêm phòng cam kết trước khi bị tính phí bồi thường.",en:"Allowed shortfall against committed room nights before a penalty applies."},{term:"Cut-off date",vi:"Ngày chốt khối phòng; sau ngày này phòng chưa đặt được trả lại cho khách sạn.",en:"Room block deadline after which unbooked rooms return to the hotel."},{term:"BEO",vi:"Phiếu yêu cầu dịch vụ tiệc ghi chi tiết bố trí phòng, thực đơn, thiết bị và thời gian.",en:"Banquet event order detailing room setup, menu, equipment and timing."},{term:"Cabaret setup",vi:"Kiểu bố trí bàn tròn chỉ xếp ghế ở phần bàn hướng về sân khấu, phù hợp thảo luận nhóm.",en:"Round tables seated only on the side facing the stage, suited to group work."}],quiz:[{q:{vi:"Hợp đồng cam kết 200 đêm phòng, cho phép hụt 10%, giá 2.000.000 đồng/đêm; thực tế dùng 170 đêm. Phí bồi thường là bao nhiêu?",en:"A contract commits 200 room nights with 10% attrition at 2,000,000 VND per night; actual use is 170 nights. What is the charge?"},options:{vi:["60.000.000 đồng","40.000.000 đồng","0 đồng","20.000.000 đồng"],en:["60,000,000 VND","40,000,000 VND","0 VND","20,000,000 VND"]},answer:3,explain:{vi:"Mức tối thiểu = 200 x 90% = 180 đêm; hụt vượt mức = 180 - 170 = 10 đêm; phí = 10 x 2.000.000 = 20.000.000 đồng.",en:"Minimum = 200 x 90% = 180 nights; excess shortfall = 180 - 170 = 10 nights; charge = 10 x 2,000,000 = 20,000,000 VND."}},{q:{vi:"Cut-off date trong hợp đồng khối phòng là gì?",en:"What is the cut-off date in a room block contract?"},options:{vi:["Ngày khai mạc sự kiện","Ngày thanh toán cuối cùng","Ngày chốt, sau đó phòng chưa đặt được trả lại khách sạn","Ngày khách sạn gửi hóa đơn"],en:["Event opening day","Final payment date","Deadline after which unbooked rooms return to the hotel","Date the hotel sends the invoice"]},answer:2,explain:{vi:"Sau ngày chốt, khách sạn được bán phòng chưa đặt cho khách khác và điều khoản hụt bắt đầu được tính.",en:"After the cut-off, the hotel may resell unbooked rooms and the attrition terms start to apply."}},{q:{vi:"Khách hàng muốn đặt backdrop chắn một cửa thoát hiểm cho đẹp sân khấu. Bạn làm gì?",en:"The client wants a backdrop placed across a fire exit for a better stage look. What do you do?"},options:{vi:["Từ chối, giữ lối thoát nạn thông thoáng và đề xuất phương án sân khấu khác","Đồng ý nếu có người đứng canh cửa","Đồng ý trong giờ khai mạc","Hỏi ý kiến đại biểu"],en:["Refuse, keep the escape route clear and propose another stage design","Agree if someone guards the door","Agree only for the opening","Ask the delegates"]},answer:0,explain:{vi:"Lối thoát nạn phải luôn thông thoáng khi có người trong phòng; không có ngoại lệ vì lý do thẩm mỹ.",en:"Escape routes must stay clear whenever people are inside; there is no exception for aesthetics."}},{q:{vi:"Phiên đào tạo cần học viên ghi chép, dùng máy tính và nhìn lên màn hình chiếu. Kiểu bố trí phù hợp nhất là gì?",en:"A training session needs note-taking, laptops and a view of the screen. Which setup fits best?"},options:{vi:["Theater","Classroom","Banquet","Cocktail"],en:["Theater","Classroom","Banquet","Cocktail"]},answer:1,explain:{vi:"Classroom có hàng bàn hướng về màn hình, đủ mặt bàn để ghi chép và đặt máy tính.",en:"Classroom uses rows of tables facing the screen with room for notes and laptops."}}],tools_en:["Event management and registration software","Event floor plan design software","Event budget and final accounts sheet","Detailed run-of-show script","QR code check-in app"]}}})})(window.KKR);
